record.field:
apps_msg_extra = ''
env['dynamic.dashboard'].seed_chart_demo_data(force=False)
apps = env['dynamic.dashboard'].search([
    ('name', 'in', [
        'Demo - Sales (All Data Sources)',
        'Demo - Purchase (All Data Sources)',
        'Demo - Inventory (All Data Sources)',
        'Demo - Accounting (All Data Sources)',
    ]),
])
if apps:
    apps_msg_extra = ' Business dashboards: ' + ', '.join(apps.mapped('name'))
else:
    apps_msg_extra = ' Install Sale/Purchase/Stock/Accounting then re-run to add business dashboards.'
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Demo data ready',
        'message': 'Created depends-only demos (partners/metrics/charts).' + apps_msg_extra,
        'type': 'success',
        'sticky': False,
    },
}

env['dynamic.dashboard'].seed_chart_demo_data(force=True)
apps = env['dynamic.dashboard'].search([
    ('name', 'in', [
        'Demo - Sales (All Data Sources)',
        'Demo - Purchase (All Data Sources)',
        'Demo - Inventory (All Data Sources)',
        'Demo - Accounting (All Data Sources)',
    ]),
])
msg = 'Rebuilt depends-only demos.'
if apps:
    msg += ' Business dashboards: ' + ', '.join(apps.mapped('name'))
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Demo data regenerated',
        'message': msg,
        'type': 'success',
        'sticky': False,
    },
}

apps = env['dynamic.dashboard'].seed_business_app_dashboards(force=True)
if apps:
    message = 'Created/updated: ' + ', '.join(apps)
    ntype = 'success'
else:
    message = 'No Sale / Purchase / Stock / Accounting modules are installed in this database.'
    ntype = 'warning'
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Business app dashboards',
        'message': message,
        'type': ntype,
        'sticky': False,
    },
}

dashes = env['dynamic.dashboard'].seed_data_calculation_type_demos(force=True)
names = ', '.join(dashes.mapped('name')) if dashes else 'none'
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Data Calculation Type demos ready',
        'message': 'Dashboards: ' + names,
        'type': 'success',
        'sticky': False,
    },
}
